1109	/**
1110	 * Build the `/safety/:id` response from one code-safety run directory (a live
1111	 * `.code-safety/<id>` or a recorded `data/code-safety/<id>`, see
1112	 * {@link resolveCodeSafetyRunDir}): walks the reviewed target for its file
1113	 * inventory, reads `findings.json` and the verifier reading, and folds both
1114	 * against the six fixed code-safety departments so every department is
1115	 * reported even with zero findings. A finding is attributed to its
1116	 * department by an explicit `department` field when present, else by its
1117	 * `id` prefix (`access-idor-allocations` names `access`) — see
1118	 * {@link SafetyFinding}. Per-severity `certificate.counts` are tallied from
1119	 * `findings` directly, the one source both a live and a recorded run always
1120	 * has, rather than trusted to a verifier reading that carries no counts in
1121	 * either real format.
1122	 * @param discoveryRoot - where the run directory lives.
1123	 * @param id - the run id.
1124	 * @returns the safety detail, or `undefined` when the run does not exist.
1125	 */
1126	export function buildSafetyDetail(discoveryRoot: string, id: string): SafetyDetail | undefined {
1127	  const runDir = resolveCodeSafetyRunDir(discoveryRoot, id)
1128	  if (runDir === undefined) return undefined
1129	
1130	  const targetRoot = resolveCodeSafetyTargetRoot(runDir)
1131	  const targetPath = targetRoot !== undefined && existsSync(targetRoot) ? targetRoot : runDir
1132	  const files: SafetyTargetFile[] = walkFiles(targetPath).map((absolute) => {
1133	    const path = relative(targetPath, absolute)
1134	    const bytes = (() => {
1135	      try {
1136	        return statSync(absolute).size
1137	      } catch {
1138	        return 0
1139	      }
1140	    })()
1141	    return { path, bytes, language: languageForPath(path) }
1142	  })
1143	  const languages: Record<string, number> = {}
1144	  for (const file of files) languages[file.language] = (languages[file.language] ?? 0) + 1
1145	
1146	  const releaseDir = resolveCodeSafetyReleaseDir(runDir)
1147	  const findings = (readJsonSafe(join(releaseDir, 'findings.json')) as SafetyFinding[] | undefined) ?? []
1148	  const counts: Record<FeedSeverity, number> = { critical: 0, high: 0, medium: 0, low: 0, info: 0 }
1149	  for (const finding of findings) {
1150	    if (finding.severity !== undefined && finding.severity in counts) counts[finding.severity] += 1
1151	  }
1152	  const certificate = { ...readVerifier(runDir) ?? normalizeCertificate({}), counts }
1153	  const departments: SafetyDepartmentStatus[] = CODE_SAFETY_DEPARTMENTS.map((department) => {
1154	    const departmentFindings = findings.filter(finding => finding.department === department.id
1155	      || (finding.department === undefined && typeof finding.id === 'string' && finding.id.startsWith(`${department.id}-`)))
1156	    const certified = certificate.verified && !certificate.unverified.includes(department.id)
1157	    return {
1158	      id: department.id,
1159	      name: department.name,
1160	      status: departmentFindings.length > 0 ? 'findings' : certificate.verified ? 'clean' : 'pending',
1161	      certified,
1162	      findings: departmentFindings.length,
1163	    }
1164	  })
1165	  const reportPath = join(releaseDir, 'SAFETY-REPORT.md')
1166	  const report = { markdown: existsSync(reportPath) ? readFileSync(reportPath, 'utf8') : '' }
1167	
1168	  return {
1169	    target: { name: id, path: targetPath, files, languages },
1170	    departments,
1171	    findings,
1172	    certificate,
1173	    report,
1174	  }
1175	}
