1177	// ---------------------------------------------------------------------------
1178	// HTTP plumbing
1179	// ---------------------------------------------------------------------------
1180	
1181	/** Headers set on every response, including the SSE stream, so the front end can be served from a different origin. */
1182	const CORS_HEADERS: Record<string, string> = {
1183	  'Access-Control-Allow-Origin': '*',
1184	  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
1185	  'Access-Control-Allow-Headers': 'Content-Type',
1186	}
1187	
1188	function sendJson(res: ServerResponse, status: number, body: unknown): void {
1189	  const payload = JSON.stringify(body)
1190	  res.writeHead(status, { ...CORS_HEADERS, 'Content-Type': 'application/json; charset=utf-8' })
1191	  res.end(payload)
1192	}
1193	
1194	function sendError(res: ServerResponse, status: number, message: string): void {
1195	  sendJson(res, status, { error: message })
1196	}
1197	
1198	/** @returns the request body parsed as JSON, or `undefined` for an empty or invalid body. */
1199	async function readJsonBody(req: IncomingMessage): Promise<Record<string, unknown> | undefined> {
1200	  const chunks: Buffer[] = []
1201	  for await (const chunk of req) chunks.push(chunk as Buffer)
1202	  if (chunks.length === 0) return undefined
1203	  try {
1204	    return JSON.parse(Buffer.concat(chunks).toString('utf8')) as Record<string, unknown>
1205	  } catch {
1206	    return undefined
1207	  }
1208	}
1209	
1210	/**
1211	 * Stream-read a session-log file's lines lazily: yields nothing (never
1212	 * throws) when the file cannot be opened, skips a line that fails to parse
1213	 * (a torn write at the tail of a live file) without ending the file's
1214	 * iteration, and stops silently on a read error mid-file so one bad file
1215	 * never takes down the run's replay. Reads in chunks via `readline` rather
1216	 * than materializing the file's lines into an array, so a run's replay never
1217	 * holds more than one line in memory at a time.
1218	 * @param file - absolute path to the JSONL file.
1219	 * @yields each successfully parsed line, in file order.
1220	 */
1221	async function* streamJsonlLines(file: string): AsyncGenerator<SessionLine> {
1222	  let stream: ReturnType<typeof createReadStream>
1223	  try {
1224	    stream = createReadStream(file, { encoding: 'utf8' })
1225	  } catch {
1226	    return
1227	  }
1228	  const rl = createInterface({ input: stream, crlfDelay: Infinity })
1229	  try {
1230	    for await (const raw of rl) {
1231	      const trimmed = raw.trim()
1232	      if (trimmed.length === 0) continue
1233	      try {
1234	        yield JSON.parse(trimmed) as SessionLine
1235	      } catch {
1236	        continue
1237	      }
1238	    }
1239	  } catch {
1240	    // A read error partway through the file (permissions, or the file
1241	    // vanished under a live process) ends this file's replay early; the
1242	    // caller moves on to the next file rather than failing the whole stream.
1243	  } finally {
1244	    rl.close()
1245	    stream.destroy()
1246	  }
1247	}
1248	
1249	/**
1250	 * Resolve one session file's id and roster agent without holding its lines:
1251	 * scans for the `session` header and the first `request/header` line — the
1252	 * only two {@link mapSessionToAgentId} reads — and stops as soon as both are
1253	 * found (or the file ends). A file this small few-hundred-line-scale
1254	 * discovery root produces is scanned in well under the time its own replay
1255	 * takes, so this adds no perceptible latency ahead of the first event sent.
1256	 * @param file - absolute path to the JSONL file.
1257	 * @param roster - the generated roster to map against.
1258	 * @param fallbackAgentId - agent id to use when nothing else matches.
1259	 * @returns the file's session id (falling back to its path) and resolved agent id.
1260	 */
1261	async function resolveFileIdentity(file: string, roster: Roster, fallbackAgentId: string): Promise<{ sessionId: string; agentId: string }> {
1262	  let sessionId: string | undefined
1263	  let headerLine: SessionLine | undefined
1264	  for await (const line of streamJsonlLines(file)) {
1265	    const type = typeOf(line)
1266	    if (sessionId === undefined && type === 'session') sessionId = sessionIdOf(line, file)
1267	    if (headerLine === undefined && type === 'request/header') headerLine = line
1268	    if (sessionId !== undefined && headerLine !== undefined) break
1269	  }
1270	  const agentId = mapSessionToAgentId(headerLine === undefined ? [] : [headerLine], roster, fallbackAgentId, sessionId)
1271	  return { sessionId: sessionId ?? file, agentId }
1272	}
1273	
1274	/**
1275	 * Stream one run's folded events over Server-Sent Events: replay every event
1276	 * currently on disk file by file and event by event, then poll each session
1277	 * file every 500ms for appended lines until the client disconnects. Each
1278	 * file is scanned once for identity ({@link resolveFileIdentity}) and once
1279	 * to fold and send its events ({@link streamJsonlLines}); neither pass
1280	 * materializes the file's lines into an array, so the replay's first event
1281	 * reaches the client as soon as the first file's identity scan completes,
1282	 * not after every session file on disk has been read.
1283	 * @param res - the open response to write SSE frames to.
1284	 * @param discoveryRoot - where the run's session files live.
1285	 * @param run - the run to stream.
1286	 * @param roster - used to map each session to a roster agent.
1287	 */
1288	async function streamRunEvents(res: ServerResponse, discoveryRoot: string, run: RunSummary, roster: Roster): Promise<void> {
1289	  res.writeHead(200, {
1290	    ...CORS_HEADERS,
1291	    'Content-Type': 'text/event-stream; charset=utf-8',
1292	    'Cache-Control': 'no-cache',
1293	    Connection: 'keep-alive',
1294	  })
1295	  const fallbackAgentId = roster.agents[0]?.id ?? ''
1296	  const files = sessionFilesForRun(discoveryRoot, run)
1297	  const offsetByFile = new Map<string, number>()
1298	  const stateByFile = new Map<string, FoldState>()
1299	  const agentIdByFile = new Map<string, string>()
1300	
1301	  const send = (event: FoldedEvent, agentId: string): void => {
1302	    res.write(`id: ${event.seq}\ndata: ${JSON.stringify({ ...event, agentId })}\n\n`)
1303	  }
1304	
1305	  for (const file of files) {
1306	    const { sessionId, agentId } = await resolveFileIdentity(file, roster, fallbackAgentId)
1307	    const state: FoldState = { sessionId, callNameById: new Map() }
1308	    stateByFile.set(file, state)
1309	    agentIdByFile.set(file, agentId)
1310	    for await (const line of streamJsonlLines(file)) {
1311	      const event = foldSessionEvent(line, state)
1312	      if (event !== undefined) send(event, agentId)
1313	    }
1314	    try {
1315	      offsetByFile.set(file, statSync(file).size)
1316	    } catch {
1317	      offsetByFile.set(file, 0)
1318	    }
1319	  }
1320	
1321	  const poll = setInterval(() => {
1322	    for (const file of files) {
1323	      let size: number
1324	      try {
1325	        size = statSync(file).size
1326	      } catch {
1327	        continue
1328	      }
1329	      const lastOffset = offsetByFile.get(file) ?? 0
1330	      if (size <= lastOffset) continue
1331	      let appended: string
1332	      try {
1333	        appended = readFileSync(file, 'utf8').slice(lastOffset)
1334	      } catch {
1335	        continue
1336	      }
1337	      offsetByFile.set(file, size)
1338	      const state = stateByFile.get(file) ?? { sessionId: file, callNameById: new Map() }
1339	      const agentId = agentIdByFile.get(file) ?? fallbackAgentId
1340	      for (const raw of appended.split('\n')) {
1341	        const trimmed = raw.trim()
1342	        if (trimmed.length === 0) continue
1343	        let parsed: SessionLine
1344	        try {
1345	          parsed = JSON.parse(trimmed) as SessionLine
1346	        } catch {
1347	          continue
1348	        }
1349	        const event = foldSessionEvent(parsed, state)
1350	        if (event !== undefined) send(event, agentId)
1351	      }
1352	    }
1353	  }, 500)
1354	
1355	  res.on('close', () => { clearInterval(poll) })
1356	}
1357	
1358	/** Options accepted by {@link createHarnessFeedServer}. */
1359	export interface HarnessFeedOptions {
1360	  /** Repository root; `data/enterprise/roster.json` always loads from here. */
1361	  root: string
1362	  /** When set, run/session/safety discovery reads this directory instead of `root`. */
1363	  fixturesDir?: string
1364	  /** Fold every session file once as soon as the server exists, so the first `GET /roster` answers from the per-file cache. */
1365	  warm?: boolean
1366	}
1367	
1368	/**
1369	 * Build the feed's HTTP server without starting it, so tests can `.listen(0)`
1370	 * on an ephemeral port.
1371	 * @param options - repository root and optional fixtures override.
1372	 * @returns an unstarted `http.Server`.
1373	 */
1374	export function createHarnessFeedServer(options: HarnessFeedOptions): Server {
1375	  const { root } = options
1376	  const discoveryRoot = options.fixturesDir ?? root
1377	
1378	  const loadRoster = (): Roster => {
1379	    const raw = readFileSync(join(root, 'data/enterprise/roster.json'), 'utf8')
1380	    return JSON.parse(raw) as Roster
1381	  }
1382	
1383	  if (options.warm === true) {
1384	    setImmediate(() => {
1385	      try {
1386	        computeLiveRoster(loadRoster(), discoveryRoot)
1387	      } catch {
1388	        // A missing or malformed roster file: the first GET /roster reports it to the caller.
1389	      }
1390	    })
1391	  }
1392	
1393	  return createServer((req, res) => {
1394	    void handleRequest(req, res).catch((error: unknown) => {
1395	      if (!res.headersSent) sendError(res, 500, error instanceof Error ? error.message : String(error))
1396	    })
1397	  })
1398	
1399	  async function handleRequest(req: IncomingMessage, res: ServerResponse): Promise<void> {
1400	    if (req.method === 'OPTIONS') {
1401	      res.writeHead(204, CORS_HEADERS)
1402	      res.end()
1403	      return
1404	    }
1405	    const url = new URL(req.url ?? '/', 'http://localhost')
1406	    const { pathname } = url
1407	
1408	    if (req.method === 'GET' && pathname === '/roster') {
1409	      sendJson(res, 200, computeLiveRoster(loadRoster(), discoveryRoot))
1410	      return
1411	    }
1412	    if (req.method === 'GET' && pathname === '/runs') {
1413	      sendJson(res, 200, discoverRuns(discoveryRoot))
1414	      return
1415	    }
1416	    const eventsMatch = /^\/runs\/([^/]+)\/events$/.exec(pathname)
1417	    if (req.method === 'GET' && eventsMatch !== null) {
1418	      const run = discoverRuns(discoveryRoot).find(candidate => candidate.id === eventsMatch[1])
1419	      if (run === undefined) {
1420	        sendError(res, 404, `no run "${eventsMatch[1]}"`)
1421	        return
1422	      }
1423	      // Fire-and-forget: the SSE stream outlives this request handler. A
1424	      // rejection here is unexpected (every per-line and per-file failure
1425	      // inside streamRunEvents is already caught), so this only ends a
1426	      // response left hanging open rather than leaving the connection stuck.
1427	      void streamRunEvents(res, discoveryRoot, run, loadRoster()).catch((error: unknown) => {
1428	        console.error(`harness-feed: streaming run "${run.id}" failed: ${error instanceof Error ? error.message : String(error)}`)
1429	        if (!res.writableEnded) res.end()
1430	      })
1431	      return
1432	    }
1433	    const safetyMatch = /^\/safety\/([^/]+)$/.exec(pathname)
1434	    const safetyId = safetyMatch?.[1]
1435	    if (req.method === 'GET' && safetyId !== undefined) {
1436	      const detail = buildSafetyDetail(discoveryRoot, safetyId)
1437	      if (detail === undefined) {
1438	        sendError(res, 404, `no code-safety run "${safetyId}"`)
1439	        return
1440	      }
1441	      sendJson(res, 200, detail)
1442	      return
1443	    }
1444	    if (req.method === 'POST' && pathname === '/safety') {
1445	      await handleStartSafety(req, res, root)
1446	      return
1447	    }
1448	    sendError(res, 404, `no route for ${req.method ?? 'GET'} ${pathname}`)
1449	  }
1450	}
1451	
1452	/** Whether `package.json` at `root` declares a `code-safety` script; the parallel workstream adds it, not this change. */
1453	function hasCodeSafetyScript(root: string): boolean {
1454	  const pkg = readJsonSafe(join(root, 'package.json')) as { scripts?: Record<string, string> } | undefined
1455	  return typeof pkg?.scripts?.['code-safety'] === 'string'
1456	}
1457	
1458	async function handleStartSafety(req: IncomingMessage, res: ServerResponse, root: string): Promise<void> {
1459	  if (!hasCodeSafetyScript(root)) {
1460	    sendError(res, 501, 'pnpm run code-safety is not defined yet; the code-safety scanner ships in a parallel change')
1461	    return
1462	  }
1463	  const body = await readJsonBody(req)
1464	  const target = body?.target
1465	  if (typeof target !== 'string' || target.length === 0) {
1466	    sendError(res, 400, 'POST /safety requires a non-empty "target"')
1467	    return
1468	  }
1469	  const model = typeof body?.model === 'string' ? body.model : undefined
1470	  // The id is the run directory's name under `.code-safety/`, the same
1471	  // `<target basename>-<stamp>` the script would choose on its own, passed as
1472	  // `--out` so the id this response returns is the id the run is discovered under.
1473	  const stamp = new Date().toISOString().replaceAll(/[:.]/g, '-').slice(0, 19)
1474	  const id = `${basename(target)}-${stamp}`
1475	  const args = ['run', 'code-safety', '--', target, '--out', join(root, '.code-safety', id), ...model === undefined ? [] : ['--model', model]]
1476	  const child = spawn('pnpm', args, { cwd: root, detached: true, stdio: 'ignore' })
1477	  child.on('error', (error) => {
1478	    // Spawn failed after the response was already sent (pnpm missing from
1479	    // PATH, or the child crashed at exec) — nothing further can react to it
1480	    // from this request, so it is only logged for operator visibility.
1481	    console.error(`harness-feed: code-safety scan "${id}" failed to start: ${error.message}`)
1482	  })
1483	  child.unref()
1484	  sendJson(res, 202, { id })
1485	}
1486	
1487	// ---------------------------------------------------------------------------
1488	// CLI entry point
1489	// ---------------------------------------------------------------------------
1490	
1491	/** Parse `--port <n>` and `--fixtures <dir>` from argv, defaulting the port to {@link DEFAULT_PORT}. */
1492	export function parseHarnessFeedArgs(argv: readonly string[]): { port: number; fixturesDir?: string } {
1493	  let port = DEFAULT_PORT
1494	  let fixturesDir: string | undefined
1495	  for (let i = 0; i < argv.length; i += 1) {
1496	    if (argv[i] === '--port' && argv[i + 1] !== undefined) {
1497	      port = Number(argv[i + 1])
1498	      i += 1
1499	    } else if (argv[i] === '--fixtures' && argv[i + 1] !== undefined) {
1500	      fixturesDir = argv[i + 1]
1501	      i += 1
1502	    }
1503	  }
1504	  if (!Number.isInteger(port) || port <= 0) {
1505	    throw new Error(`harness-feed: --port must be a positive integer, got "${port}"`)
1506	  }
1507	  return { port, ...fixturesDir === undefined ? {} : { fixturesDir } }
1508	}
1509	
1510	const isMain = process.argv[1] !== undefined && import.meta.url === `file://${resolve(process.argv[1])}`
1511	if (isMain) {
1512	  const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
1513	  const { port, fixturesDir } = parseHarnessFeedArgs(process.argv.slice(2))
1514	  const server = createHarnessFeedServer({ root, warm: true, ...fixturesDir === undefined ? {} : { fixturesDir: resolve(fixturesDir) } })
1515	  server.listen(port, () => {
1516	    console.log(`harness-feed: listening on http://localhost:${port}${fixturesDir === undefined ? '' : ` (fixtures: ${fixturesDir})`}`)
1517	  })
1518	}

