"""Print the JSONL rows of one file whose `type` is in a comma-separated list.

usage: show_types.py <file> <type,type,...> [max_chars]
A `request/header` row is summarized (system/tools truncated).
"""
import json
import sys

path = sys.argv[1]
wanted = set(sys.argv[2].split(','))
limit = int(sys.argv[3]) if len(sys.argv) > 3 else 1500
with open(path) as handle:
    for raw in handle:
        raw = raw.strip()
        if not raw:
            continue
        try:
            obj = json.loads(raw)
        except ValueError:
            continue
        if obj.get('type') not in wanted:
            continue
        if obj.get('type') == 'request/header':
            header = obj.get('data', {}).get('header', {})
            summary = {}
            for key, value in header.items():
                summary[key] = str(value)[:300] if key in ('system', 'tools', 'messages') else value
            print(json.dumps({'seq': obj.get('seq'), 'time': obj.get('time'), 'header': summary})[:limit])
        else:
            print(json.dumps(obj)[:limit])

