/**
 * Classify every recorded session by what it identifies: a program member
 * (by session id), a bench environment (by its `environment/run` event), or
 * neither; and report provider stamps, environment ids, and seat coverage.
 */
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

import { discoverRuns, readJsonlLines, sessionFilesForRun } from '/home/user/deepseek-harness/.claude/worktrees/agent-a1961746d8189bdc5/scripts/harness-feed.ts'
import type { Roster } from '/home/user/deepseek-harness/.claude/worktrees/agent-a1961746d8189bdc5/scripts/enterprise-roster.ts'

const root = '/home/user/deepseek-harness/.claude/worktrees/agent-a1961746d8189bdc5'
const roster = JSON.parse(readFileSync(join(root, 'data/enterprise/roster.json'), 'utf8')) as Roster
const seatedEnvironments = new Set(roster.agents.filter(a => a.division === 'proving-ground').map(a => a.specialization))
const runs = discoverRuns(root).filter(run => run.path.startsWith('data/'))
const tally = new Map<string, number>()
const envIds = new Map<string, number>()
const envKinds = new Map<string, number>()
const otherExamples: string[] = []
const bump = (map: Map<string, number>, key: string): void => { map.set(key, (map.get(key) ?? 0) + 1) }
for (const run of runs) {
  for (const file of sessionFilesForRun(root, run)) {
    const lines = readJsonlLines(file)
    const header = lines.find(line => line.type === 'session')
    const id = typeof header?.id === 'string' ? header.id : ''
    const request = lines.find(line => line.type === 'request/header')
    const provider = (request?.data?.header as { config?: { provider?: string } } | undefined)?.config?.provider ?? 'none'
    const envRun = lines.find(line => line.type === 'environment/run')
    const envId = typeof envRun?.data?.environmentId === 'string' ? envRun.data.environmentId : undefined
    const envKind = typeof envRun?.data?.environmentKind === 'string' ? envRun.data.environmentKind : undefined
    const program = /^program-[0-9a-f]{16,}(?:-(.+))?$/.exec(id)
    let klass: string
    if (program !== null) {
      klass = `program:${run.kind}:${program[1] === undefined ? 'lead' : program[1].startsWith('~0040') ? 'integration' : 'member'}`
    } else if (envId !== undefined) {
      const name = envId.replace(/^[a-z]+:/, '')
      klass = `environment:${seatedEnvironments.has(name) ? 'seated' : 'unseated'}`
      bump(envIds, envId)
      bump(envKinds, envKind ?? '?')
    } else {
      klass = 'other'
      if (otherExamples.length < 12) otherExamples.push(`${run.id} ${id} types=${[...new Set(lines.map(l => String(l.type)))].slice(0, 12).join(',')}`)
    }
    bump(tally, `${klass} provider=${provider}`)
  }
}
console.log(JSON.stringify({
  seatedEnvironments: [...seatedEnvironments],
  tally: Object.fromEntries([...tally].sort()),
  envIds: Object.fromEntries([...envIds].sort((a, b) => b[1] - a[1])),
  envKinds: Object.fromEntries(envKinds),
  otherExamples,
}, null, 2))

