if (run === undefined) throw new Error(`no run ${wanted}`)
let shown = 0
for (const file of sessionFilesForRun(root, run)) {
  const lines = readJsonlLines(file)
  const header = lines.find(line => line.type === 'session')
  const id = typeof header?.id === 'string' ? header.id : ''
  if (/^program-/.test(id) || lines.some(line => line.type === 'environment/run') || header?.origin === 'subagent') continue
  if (shown >= 3) break
  shown += 1
  console.log(file.split('/').slice(-1)[0], JSON.stringify(header))
  console.log('  types:', lines.slice(0, 14).map(line => String(line.type)).join(', '))
  for (const line of lines.filter(l => l.type === 'goal/change' || l.type === 'environment/delegation' || l.type === 'verification/standard').slice(0, 2)) {
    console.log('  ', JSON.stringify(line).slice(0, 400))
  }
}

