for (const file of files) lines += readJsonlLines(file).length
console.log(`full JSON.parse: ${files.length} files, ${lines} lines, ${Math.round(performance.now() - started)} ms`)

// A scan that parses only the lines whose `type` it needs, found by a cheap prefix test.
started = performance.now()
let parsed = 0
const WANTED = ['"type":"session"', '"type":"request/header"', '"type":"environment/run"', '"type":"verification/certificate"', '"type":"program/']
for (const file of files) {
  const text = readFileSync(file, 'utf8')
  for (const raw of text.split('\n')) {
    if (raw.length === 0) continue
    const head = raw.slice(0, 48)
    if (WANTED.some(prefix => head.includes(prefix))) {
      JSON.parse(raw)
      parsed += 1
    }
  }
}
console.log(`selective parse: ${parsed} lines parsed, ${Math.round(performance.now() - started)} ms`)

