/** Mutable per-seat tally {@link summarizeEvidence} builds before it freezes each into a {@link SeatEvidence}. */
interface SeatTally {
  sessions: number
  lastSeenMs?: number
  routes: Set<string>
}

/**
 * Summarize attributed runs into per-seat evidence, the records read, sessions
