/*
 * The deck's visual system: one dark ground, one luminous accent per meaning,
 * and type that stays quiet so the scene carries the image.
 */

:root {
  --bg: #04060b;
  --bg-2: #070b13;
  --panel: rgba(10, 15, 25, 0.78);
  --panel-solid: #0a0f19;
  --raised: rgba(24, 33, 50, 0.6);
  --line: rgba(122, 152, 205, 0.16);
  --line-strong: rgba(122, 152, 205, 0.32);

  --ink: #e8eefc;
  --ink-2: #a2b2ce;
  --ink-3: #64749a;

  --cyan: #4fd8ff;
  --violet: #9b7bff;
  --amber: #ffbe5c;
  --green: #49e0a6;
  --red: #ff3f6b;

  --critical: #ff3f6b;
  --high: #ff8a3d;
  --medium: #ffc94d;
  --low: #4fd8ff;
  --info: #7f8fb0;

  --font-ui: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;

  --header: 52px;
  --footer: 30px;
  --panel-w: 400px;
  --radius: 10px;
}

* { box-sizing: border-box; }

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: 13px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  font-variant-numeric: tabular-nums;
}

/* ---------------------------------------------------------------- panel -- */

.panel {
  border-left: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(9, 14, 23, 0.9), rgba(5, 9, 15, 0.96));
  backdrop-filter: blur(14px);
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.panel__head {
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.panel__eyebrow {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--ink-3);
}

.panel__title { margin: 5px 0 0; font-size: 15px; font-weight: 550; letter-spacing: -0.01em; }
.panel__sub { margin: 3px 0 0; font-size: 11.5px; color: var(--ink-2); }

.panel__body { flex: 1; min-height: 0; overflow-y: auto; padding: 14px 16px 24px; }

.panel__empty {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 26px 16px;
  color: var(--ink-3);
  font-size: 12px;
}

.field { display: grid; grid-template-columns: 96px 1fr; gap: 8px; padding: 5px 0; align-items: baseline; }
.field dt { font-size: 10px; text-transform: uppercase; letter-spacing: 0.14em; color: var(--ink-3); }
.field dd { margin: 0; font-size: 12px; color: var(--ink); word-break: break-word; }
.field dd.mono { font-family: var(--font-mono); font-size: 11px; color: var(--ink-2); }

.section { margin-top: 18px; }
.section > h3 {
  margin: 0 0 8px;
  font-size: 9.5px;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--ink-3);
  font-weight: 600;
}

.chips { display: flex; flex-wrap: wrap; gap: 5px; }

.chip {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--ink-2);
  border: 1px solid var(--line);
  background: rgba(122, 152, 205, 0.06);
  border-radius: 5px;
  padding: 2px 7px;
}

.chip[data-tone='tool'] { color: var(--cyan); border-color: rgba(79, 216, 255, 0.25); }
.chip[data-tone='skill'] { color: var(--violet); border-color: rgba(155, 123, 255, 0.25); }

.status-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
.sev[data-s='info'] { color: var(--info); }

/* ---------------------------------------------------------------- cards -- */

.card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(122, 152, 205, 0.04);
  padding: 12px 13px;
}

.card--verified { border-color: rgba(73, 224, 166, 0.32); background: rgba(73, 224, 166, 0.05); }

.card__head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.card__head h4 { margin: 0; font-size: 12.5px; font-weight: 550; }

.tally { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; margin-top: 11px; }
.tally > div { text-align: center; border: 1px solid var(--line); border-radius: 7px; padding: 6px 2px; }
.tally b { display: block; font-size: 15px; font-weight: 600; line-height: 1.1; }
.tally span { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.1em; color: var(--ink-3); }

.snippet {
  font-family: var(--font-mono);
  font-size: 10.5px;
  line-height: 1.6;
  color: #cfe3ff;
  background: rgba(3, 6, 12, 0.85);
  border: 1px solid var(--line);
  border-left: 2px solid var(--critical);
  border-radius: 7px;
  padding: 9px 11px;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-word;
  margin: 0;
}

.tabs { display: flex; gap: 3px; padding: 10px 16px 0; border-bottom: 1px solid var(--line); }

.tabs button {
  appearance: none;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--ink-3);
  font-family: inherit;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  padding: 5px 9px 8px;
  cursor: pointer;
}

.tabs button[data-active='true'] { color: var(--ink); border-bottom-color: var(--cyan); }

.filters { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }

/* ------------------------------------------------------- finding detail -- */

.finding-card {
  position: absolute;
  font-size: 9px;
  color: var(--ink-3);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 0 4px;
  line-height: 14px;
}

.deck__spacer { flex: 1; }

.deck__counts { display: flex; gap: 18px; }

.count { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.15; }
.count b { font-size: 15px; font-weight: 600; letter-spacing: -0.01em; }
.count span { font-size: 9px; text-transform: uppercase; letter-spacing: 0.16em; color: var(--ink-3); }
.count[data-tone='active'] b { color: var(--cyan); }
.count[data-tone='certified'] b { color: var(--green); }
/* Lit while the number is travelling, so the eye catches that it moved. */
.count [data-rolling='true'] { text-shadow: 0 0 16px currentColor; }

.deck__main {

/** Display formatting shared by every panel. */

/**
 * Clock time of one timestamp, in the viewer's locale.
 * @param at - ISO-8601 text (a run's `startedAt`) or epoch milliseconds (an event's `ts`).
 * @returns `HH:MM:SS`, or `--:--:--` when the timestamp does not parse.
 */
export function clock(at: string | number): string {
  const date = new Date(at)
  if (Number.isNaN(date.getTime())) return '--:--:--'
  return date.toLocaleTimeString('en-GB', { hour12: false })
}

/**
 * Date and clock time of one timestamp.
 * @param at - ISO-8601 text or epoch milliseconds.
 * @returns `YYYY-MM-DD HH:MM`, or `—` when the timestamp does not parse.
 */
export function stamp(at: string | number): string {
  const date = new Date(at)
  if (Number.isNaN(date.getTime())) return '—'
  return `${date.toISOString().slice(0, 10)} ${date.toISOString().slice(11, 16)}`
}

/**
 * Human-readable byte count.
 * @param bytes - Size in bytes.
 * @returns A short size such as `6.1 kB`.
 */
export function bytes(value: number): string {
  if (value < 1024) return `${value} B`
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} kB`
  return `${(value / (1024 * 1024)).toFixed(1)} MB`
}

/**
 * Duration between two ISO timestamps.
 * @param from - Start timestamp.
 * @param to - End timestamp; the current time when omitted.
 * @returns A compact duration such as `34m 12s`.
 */
export function duration(from: string, to?: string): string {
  const start = new Date(from).getTime()
  const end = to === undefined ? Date.now() : new Date(to).getTime()
  if (Number.isNaN(start) || Number.isNaN(end)) return '—'
  const seconds = Math.max(0, Math.round((end - start) / 1000))
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return `${minutes}m ${String(seconds % 60).padStart(2, '0')}s`
  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`
}
'use client'

import type { ReactNode } from 'react'
import { useDeck } from '@/deck/store'

/**
 * The standing statement that what is on screen is example data.
 *
 * It is shown inside every view's panel rather than once in the shell, because
 * a screenshot of a single view must carry the claim with it.
 * @returns The notice in replay mode, and nothing when the feed is live.
 */
export function ReplayNotice(): ReactNode {
  const source = useDeck(state => state.source)
  if (source?.mode !== 'replay') return null
  return (
    <div className="notice">
      <b>Example data.</b>
      <span>
        The feed at {source.configured} is not answering, so the deck is replaying the fixtures committed with it.
        Nothing on screen comes from a live run.
      </span>
    </div>
  )
}
