  await page.locator('.panel__body').evaluate((element) => { element.scrollTop = 0 })

  // Sweep the pointer over the dim clusters until the hover label names a never-run seat.
  let hovered
  const regions = [[790, 590, 900, 700], [230, 395, 320, 480], [560, 195, 690, 320], [820, 360, 950, 470]]
  for (const [left, top, right, bottom] of regions) {
    for (let y = top; y <= bottom && hovered === undefined; y += 5) {
      for (let x = left; x <= right; x += 5) {
        await page.mouse.move(x, y)
        await page.waitForTimeout(25)
        if (await page.getByText('defined, never run', { exact: true }).count() > 0) {
          hovered = [x, y]
          break
        }
      }
    }
    if (hovered !== undefined) break
  }
  await page.waitForTimeout(400)
  await page.screenshot({ path: `${out}/enterprise.png` })
  const routes = await page.locator('.routes').first().innerText()

  await page.mouse.move(5, 880)
  await page.locator('.tabs button', { hasText: 'Record' }).click()
  await page.waitForSelector('.record', { timeout: 30_000 })
  await page.waitForTimeout(1_500)
  await page.screenshot({ path: `${out}/record.png` })
  console.log(JSON.stringify({ hovered, routes, failed }))
} finally {
  await browser.close()
}

