/** Group the committed records' unattributed sessions by reason and by the kind of id they carry. */
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

import { attributeRun, committedRecords, readRecordedSessions } from '/home/user/deepseek-harness/.claude/worktrees/agent-a1961746d8189bdc5/scripts/roster-evidence.ts'
import type { Roster } from '/home/user/deepseek-harness/.claude/worktrees/agent-a1961746d8189bdc5/scripts/enterprise-roster.ts'

const root = '/home/user/deepseek-harness/.claude/worktrees/agent-a1961746d8189bdc5'
const roster = JSON.parse(readFileSync(join(root, 'data/enterprise/roster.json'), 'utf8')) as Roster
const tally = new Map<string, number>()
for (const run of readRecordedSessions(root, committedRecords(root))) {
  for (const { facts, attribution } of attributeRun(run, roster.agents)) {
    if (attribution.kind !== 'unattributed') continue
    const kind = facts.sessionId.split('-')[0] ?? '?'
    const key = `${attribution.reason} ${kind}${facts.parentSessionId === undefined ? '' : ' (delegated)'}`
    tally.set(key, (tally.get(key) ?? 0) + 1)
  }
}
console.log(Object.fromEntries([...tally].sort()))

